  const base = { actor: d.actor, at: d.at, before_amount: adjustment?.before, before_account: adjustment?.before_account };
  if (d.action === 'confirm') return { ...base, action: 'accept', note: d.note };
  if (d.note.startsWith(EXCLUDE_TAG)) return { ...base, action: 'exclude', note: d.note.slice(EXCLUDE_TAG.length).trim() };
  return { ...base, action: 'adjust', note: d.note, account_code: d.account_code || undefined, amount: adjustment?.amount };
}

export function toException(p: Pendencia, index: DataIndex, adjustments = loadAdjustments()): ReviewException {
  const step = index.stepOfPendencia.get(p.id_saida) || 'comissao_checkout';
  const orbe = index.orbeById.get(p.ref_origem);
  const remittance = index.remittanceById.get(p.ref_origem);
  const bank = index.bankByRef.get(p.ref_origem);
  const line = index.lancamentoByRef.get(p.ref_origem);
  const isBank = step === 'classificar_bancos' && !!line;
  return {
    id: p.id_saida,
    step_type: step,
    step_title: stepTitle(step),
    kind: p.tipo,
    title: p.tipo,
    severity: severityOf(p),
    original_severity: p.severity,
    merchant: p.cnpj ? merchantName(index, p.cnpj, orbe?.name || remittance?.name) : orbe?.name || remittance?.name || (bank ? `Banco ${bank.bank}` : '—'),
    cnpj: p.cnpj,
    date: orbe?.date || remittance?.contracted_date || bank?.date,
    amount: orbe?.gross || remittance?.gross_brl || bank?.amount || undefined,
    impact_brl: p.valor_brl,
    description: p.motivo,
    suggestion: p.suggestion,
    rule: p.rule,
    who_decides: p.quem_decide,
    ref_origem: p.ref_origem,
    evidence: p.evidence || [],
    bank_line_id: isBank ? line!.id_saida : undefined,
    current_account: isBank ? line!.conta_codigo : undefined,
    decision: decisionOf(p, adjustments[p.id_saida]),
  };
}

export async function listExceptions(run: Run): Promise<ReviewException[]> {
  const index = indexState(await loadState());
  const adjustments = loadAdjustments();
  return activePendencias(index, run, true).map(p => toException(p, index, adjustments));
}

export async function excludedRefs(run: Run) {
  const list = await listExceptions(run);
  return new Set(list.filter(item => item.decision?.action === 'exclude' && item.bank_line_id).map(item => item.ref_origem));
}

export async function approvalSummary(run: Run): Promise<ApprovalSummary> {
  const index = indexState(await loadState());
  const list = await listExceptions(run);
  const excluded = new Set(list.filter(item => item.decision?.action === 'exclude' && item.bank_line_id).map(item => item.ref_origem));
  const entries = fenixEntries(index, excluded);
  const total = entries.reduce((sum, entry) => sum + cents(entry.valor), 0n);
  const blocking = list.filter(item => item.severity === 'bloqueante');
  const open = list.filter(item => !item.decision);
  return {
    total: list.length,
    blocking: blocking.length,
    alerts: list.length - blocking.length,
    decided: list.length - open.length,
    open_blocking: open.filter(item => item.severity === 'bloqueante').length,
    open_alerts: open.filter(item => item.severity === 'alerta').length,
    impact_brl: fromCents(list.reduce((sum, item) => sum + absUnits(cents(item.impact_brl)), 0n)),
    open_impact_brl: fromCents(open.reduce((sum, item) => sum + absUnits(cents(item.impact_brl)), 0n)),
    // Each Fênix entry debits and credits the same amount, so the batch balances by construction.
    batch: { entries: entries.length, excluded: excluded.size, debit_brl: fromCents(total), credit_brl: fromCents(total), balanced: true },
  };
}

export async function decide(
  run: Run, exceptionId: string, input: { action: ReviewDecision['action']; note: string; account_code?: string; amount?: string },
): Promise<ReviewException> {
  await ensureActor();
  if (run.status !== 'awaiting_approval') throw new ApiError('A revisão só aceita decisões enquanto o run aguarda aprovação.', 409);
  const current = (await listExceptions(run)).find(item => item.id === exceptionId);
  if (!current) throw new ApiError('Exceção não encontrada neste run.', 404);
  const note = input.note.trim();
  if (input.action !== 'accept' && !note) throw new ApiError('A justificativa é obrigatória para ajustar ou excluir do lote.', 400);
  if (input.action === 'adjust' && !input.account_code && !input.amount) {
    throw new ApiError('Informe a nova conta ou o valor ajustado.', 400);
  }
  if (input.amount) cents(input.amount);

  let text = note || `Aceito na revisão do ${run.id}.`;
  if (input.action === 'adjust' && input.amount) text = `${text} Valor proposto: ${money(input.amount)} (antes ${money(current.impact_brl)}).`;
  if (input.action === 'exclude') text = `${EXCLUDE_TAG} ${text}`;
  await core.decide({
    id: exceptionId,
    action: input.action === 'accept' ? 'confirm' : 'adjust',
    note: text,
    ...(input.action === 'adjust' && input.account_code ? { account_code: input.account_code } : {}),
  });
  saveAdjustment(exceptionId, input.action === 'adjust'
    ? { amount: input.amount || '', before: current.impact_brl ?? '', before_account: current.current_account, at: new Date().toISOString() }
    : null);
  const index = indexState(await refreshState());
  const updated = index.state.results.pendencias.find(p => p.id_saida === exceptionId);
  if (!updated) throw new ApiError('A exceção mudou depois do recálculo. Recarregue a revisão.', 409);
  return toException(updated, index);
}

export async function decideMany(run: Run, ids: string[], { action, note }: { action: 'accept' | 'exclude'; note: string }, onProgress?: (done: number) => void) {
  await ensureActor();
  if (run.status !== 'awaiting_approval') throw new ApiError('A revisão só aceita decisões enquanto o run aguarda aprovação.', 409);
  const byId = new Map((await listExceptions(run)).map(item => [item.id, item]));
  const chosen = ids.flatMap(id => byId.get(id) || []);
  if (chosen.some(item => item.severity === 'bloqueante') && new Set(chosen.map(item => `${item.kind}|${item.cnpj || item.merchant}`)).size !== 1) {
    throw new ApiError('Bloqueantes só são decididas em lote quando são do mesmo tipo e do mesmo lojista.', 400);
  }
  let decided = 0;
  try {
    for (const id of ids) {
      if (!byId.has(id)) continue;
      if (action === 'exclude') { await decide(run, id, { action, note }); decided += 1; onProgress?.(decided); continue; }
      await core.decide({ id, action: 'confirm', note: note.trim() || `Alerta aceito em lote na revisão do ${run.id}.` });
      saveAdjustment(id, null);
      decided += 1;
      onProgress?.(decided);
    }
  } finally {
    await refreshState();
  }
  return { decided };
}
// Conversation state of the chat dock, outside React (same external-store pattern as workbench/store.ts):
// the dock unmounts while a step's table loads, and a question in flight must keep its answer.
import { useSyncExternalStore } from 'react';
import { chat, type AskInput, type ChatAnswer, type ChatFunnel, type ChatQuery, type ChatThread, type ChatTurnRecord } from '../api/chat';
import { getActor } from '../lib/actor';
import type { Highlight } from '../workbench/contract';
import { workbench } from '../workbench/store';

export interface ChatItem {
  key: string;
  id?: string;
  pergunta: string;
  modo: 'pergunta' | 'por_que';
  autor: string;
  at: string;
  status: 'running' | 'ok' | 'erro';
  stages: string[];
  queries: ChatQuery[];
  funil: ChatFunnel | null;
  answer: ChatAnswer | null;
  error: string | null;
  input?: AskInput;
}

interface SessionState { runId: string; threadId: string | null; items: ChatItem[]; restored: boolean }

let state: SessionState = { runId: '', threadId: null, items: [], restored: false };
const listeners = new Set<() => void>();
let controller: AbortController | null = null;
let sequence = 0;

function set(patch: Partial<SessionState>) {
  state = { ...state, ...patch };
  listeners.forEach(listener => listener());
}

function update(key: string, change: (item: ChatItem) => ChatItem) {
  set({ items: state.items.map(item => (item.key === key ? change(item) : item)) });
}

export function fromRecord(turn: ChatTurnRecord): ChatItem {
  return {
    key: turn.id, id: turn.id, pergunta: turn.pergunta, modo: turn.modo || 'pergunta', autor: turn.autor, at: turn.criado_em,
    status: turn.status === 'ok' && turn.answer ? 'ok' : 'erro', stages: [], queries: turn.answer?.consultas || [], funil: turn.answer?.funil || null,
    answer: turn.answer, error: turn.erro?.message || (turn.answer ? null : 'Esta pergunta não teve resposta.'),
  };
}

/** Rows an answer points at, as a grid highlight (one answer highlighted at a time). */
export function answerHighlight(answer: ChatAnswer): Highlight | null {
  const rows = answer.linhas;
  if (!rows || !rows.rids.length) return null;
  return { id: `chat-${answer.id}`, answerId: answer.id, dataset: rows.dataset, rids: rows.rids, tone: 'info', label: rows.rotulo };
}

export function showAnswer(answer: ChatAnswer) {
  for (const item of workbench.get().highlights) if (item.answerId && item.answerId !== answer.id) workbench.clearHighlight(item.id);
  const highlight = answerHighlight(answer);
  if (highlight) workbench.highlight(highlight);
}

export const chatSession = {
  get: () => state,
  subscribe(listener: () => void) { listeners.add(listener); return () => { listeners.delete(listener); }; },

  /** A different run starts empty; the dock then restores that run's latest conversation once. */
  forRun(runId: string) {
    if (state.runId === runId) return;
    controller?.abort();
    set({ runId, threadId: null, items: [], restored: false });
  },
  restore(runId: string, threads: ChatThread[]) {
    if (state.runId !== runId || state.restored) return;
    const last = threads[0];
    set(last && !state.items.length ? { restored: true, threadId: last.id, items: last.perguntas.map(fromRecord) } : { restored: true });
  },
  /** New conversation: the next question starts a thread without the previous history. */
  reset() {
    controller?.abort();
    set({ threadId: null, items: [] });
  },
  cancel() { controller?.abort(); },
  running: () => state.items.some(item => item.status === 'running'),

  async send(input: Omit<AskInput, 'thread_id'>) {
    if (chatSession.running()) return;
    const runId = state.runId;
    const full: AskInput = { ...input, thread_id: state.threadId };
    const key = `local-${++sequence}`;
    set({ items: [...state.items, { key, pergunta: input.pergunta, modo: input.modo, autor: getActor(), at: new Date().toISOString(), status: 'running',
      stages: [], queries: [], funil: null, answer: null, error: null, input: full }] });
    controller = new AbortController();
    const mine = controller;
    try {
      await chat.ask(runId, full, event => {
        if (state.runId !== runId) return;
        switch (event.type) {
          case 'thread': set({ threadId: event.thread_id }); update(key, item => ({ ...item, id: event.message_id })); break;
          case 'stage': update(key, item => ({ ...item, stages: [...item.stages, event.texto] })); break;
          case 'query': { const { type: _type, ...query } = event; update(key, item => ({ ...item, queries: [...item.queries, query] })); break; }
          case 'funnel': update(key, item => ({ ...item, funil: event.funil })); break;
          case 'answer': update(key, item => ({ ...item, status: 'ok', answer: event.answer })); showAnswer(event.answer); break;
          case 'error': update(key, item => ({ ...item, status: 'erro', error: event.message })); break;
        }
      }, mine.signal);
      update(key, item => (item.status === 'running' ? { ...item, status: 'erro', error: 'A resposta foi interrompida antes do fim.' } : item));
    } catch (error) {
      const message = mine.signal.aborted ? 'Pergunta cancelada.' : error instanceof Error ? error.message : 'O chat não respondeu.';
      update(key, item => ({ ...item, status: 'erro', error: message }));
      // A conversation that no longer exists (other database) starts over on the next question.
      if (error instanceof Error && 'status' in error && (error as { status: number }).status === 404) set({ threadId: null });
    } finally {
      if (controller === mine) controller = null;
    }
  },
};

export function useChatSession(): SessionState {
  return useSyncExternalStore(chatSession.subscribe, chatSession.get);
}
